              { name: "romeo", email: "romeo@invalid" },
            ],
          },
          {
            addr: "TestList <TestList>",
            options: { expandMailingLists: true, preserveGroups: true },
            expected: [
              {
                name: "TestList",
                group: [
                  { name: "charlie", email: "charlie@invalid" },
                  { name: "juliet", email: "juliet@invalid" },
                  { name: "mike", email: "mike@invalid" },
